import{_ as a,o,c as t,a5 as i}from"./chunks/framework.CXvGqWf0.js";const m=JSON.parse('{"title":"漫画 · 第 13 话 表单：浏览器是第一道质检员","description":"","frontmatter":{},"headers":[],"relativePath":"comics/html/EP.13-forms.md","filePath":"comics/html/EP.13-forms.md","lastUpdated":1793421609000}'),l={name:"comics/html/EP.13-forms.md"};function d(r,e,c,s,n,h){return o(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="漫画-·-第-13-话-表单-浏览器是第一道质检员" tabindex="-1">漫画 · 第 13 话 表单：浏览器是第一道质检员 <a class="header-anchor" href="#漫画-·-第-13-话-表单-浏览器是第一道质检员" aria-label="Permalink to &quot;漫画 · 第 13 话 表单：浏览器是第一道质检员&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../../docs/html/02-forms">docs/html/02-forms.md</a> ｜ 原画：<a href="./EP.13-forms.svg">EP.13-forms.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>像素酱</strong>：CSS 造型师，被拉去写注册页——邮箱、手机号、URL 各写一套正则，还忘了移动端键盘，测试同学在手机上输入邮箱时连 <code>@</code> 都找不到。</li><li><strong>标签君</strong>：HTML5 结构师，本话主角。演示&quot;规则声明给浏览器&quot;的约束校验管线，只在两次密码一致这类业务规则上才动手写 JS。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>HTML5 表单增强把&quot;输入对不对&quot;下沉到了浏览器：语义化输入类型负责控件与移动键盘，声明式属性负责规则，Constraint Validation API 负责让 JS 读取与介入同一套校验引擎。像素酱删掉半屏正则后，表单反而更好用——错误提示统一、键盘自动适配、密码管理器也认识字段了。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p>纯手写校验有三重成本：每种字段一套正则样板、错误提示全靠自己拼、移动端键盘与字段不匹配（<code>type=&quot;text&quot;</code> 输入邮箱时键盘没有 <code>@</code>，输验证码时弹出全字母键盘）。这些逻辑每个项目都在重写，而且浏览器本来就免费提供。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p>提交表单时，浏览器走一条约束校验管线：先收集控件，依次检查 <code>typeMismatch → valueMissing → tooLong → rangeUnderflow/Overflow → stepMismatch → patternMismatch → 自定义约束</code>；任一失败就阻止提交、聚焦第一个非法控件并弹出原生气泡，同时触发不冒泡的 <code>invalid</code> 事件（全表单监听要用捕获阶段委托）。结果挂在每个控件的 <code>validity</code> 对象上，9 个布尔标志精确告诉你失败原因。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p><code>type=&quot;email/url/tel/number/date/range/color&quot;</code> 一键得到合适控件、合适键盘和内建校验；<code>inputmode=&quot;numeric&quot;</code>、<code>enterkeyhint=&quot;go&quot;</code> 进一步微调移动端体验。业务级校验（两次密码一致）用 <code>setCustomValidity(消息)</code> 把控件置为 <code>customError</code>，注意条件恢复后<strong>必须传空串复位</strong>。想完全自定义错误 UI，就给表单加 <code>novalidate</code> 接管提交时机——它只跳过自动拦截，<code>checkValidity()</code> 等 API 照常工作。样式上用 <code>:user-invalid/:user-valid</code>，用户交互后才变色，避免空表单一进页面就全红。</p><h2 id="码叔划重点" tabindex="-1">码叔划重点 <a class="header-anchor" href="#码叔划重点" aria-label="Permalink to &quot;码叔划重点&quot;">​</a></h2><ol><li>type 不只是控件名：移动端键盘、原生校验、自动填充三件事都由它决定。</li><li>规则声明给浏览器：required/pattern/min/max 提交自动拦截，JS 只管业务规则。</li><li>novalidate 只接管提交时机；setCustomValidity 修复后必须传空串复位。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：表单加了 <code>novalidate</code> 后，<code>form.checkValidity()</code> 为什么仍然返回 false？这是 bug 吗？</p><p><strong>答</strong>：不是 bug，正是 novalidate 的设计意图。<code>novalidate</code> 只关闭&quot;提交时浏览器自动拦截并弹气泡&quot;这一步，并不关闭校验引擎——控件的 <code>validity</code> 状态、<code>checkValidity()/reportValidity()</code> 全部照常计算。因此自定义验证方案的标准套路是：<code>novalidate</code> 接管提交 → JS 调 <code>checkValidity()</code> 读结果 → 按自己的样式和位置渲染错误；需要原生气泡时再调 <code>reportValidity()</code>。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ul><li>输入类型全家桶 + datalist + output + fieldset/legend + label 关联：<a href="./../../examples/html/02-forms/index-01-input-types.html">examples/html/02-forms/index-01-input-types.html</a></li><li>Constraint Validation API：validity 实时面板 + setCustomValidity + novalidate 自定义验证：<a href="./../../examples/html/02-forms/index-02-validation-api.html">index-02-validation-api.html</a></li><li>:valid/:invalid 与 :user-valid/:user-invalid 体验差异 + autocomplete：<a href="./../../examples/html/02-forms/index-03-user-valid-pseudo.html">index-03-user-valid-pseudo.html</a></li></ul><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>第 14 话《Canvas》——一块即时模式位图：时钟、粒子、柱状图与高清屏适配的标准三步。</p>',22)])])}const p=a(l,[["render",d]]);export{m as __pageData,p as default};
